<section class="container archive"><aside class="filters"><h3>Filters</h3><details open><summary>Category</summary><?php foreach ($categories as $category): ?><label><input type="radio" name="category" <?= ($_GET['category'] ?? '')===$category['slug']?'checked':''; ?>><?= e($category['name']) ?></label><?php endforeach; ?></details><details><summary>Rating</summary><label><input type="checkbox">4★ & up</label><label><input type="checkbox">3★ & up</label></details><details><summary>Type</summary><label><input type="checkbox">Trending</label><label><input type="checkbox">Best Sellers</label><label><input type="checkbox">Newest</label></details></aside><div><form method="get" class="sort-row"><input type="hidden" name="route" value="catalog"><input name="q" value="<?= e($search) ?>" placeholder="Search products"><select><option>Best Match</option><option>Best Sellers</option><option>Newest</option><option>Best Rated</option><option>Trending</option></select><button>Apply</button></form><div class="prod-grid"><?php foreach ($products as $product) require APP_ROOT . '/views/partials/product-card.php'; ?></div></div></section>
